package io.github.samlinb.openbone.io;

import java.util.*;
import org.junit.jupiter.api.Test;
import io.github.samlinb.openbone.application.*;
import io.github.samlinb.openbone.core.animation.*;
import io.github.samlinb.openbone.core.math.*;
import io.github.samlinb.openbone.core.model.*;
import static io.github.samlinb.openbone.TestData.id;
import static org.junit.jupiter.api.Assertions.*;

class Ik2PrecisionCertificateTest {
 static DocumentSnapshot original()throws Exception{try(var stream=Ik2PrecisionCertificateTest.class.getResourceAsStream("/regressions/p7-ind-01.json")){assertNotNull(stream);return new ProjectCodec().decode(stream.readAllBytes());}}
 static DocumentSnapshot safe()throws Exception{var d=original();d=ModelEdits.editBone(d,id(1),b->b.withLocal(Transform.IDENTITY));d=ModelEdits.editBone(d,id(4),b->b.withLocal(new Transform(20,60,0,1,1)));return d.withConstraints(List.of(((IkConstraint)d.constraints().get(0)).withSoftness(10).withOptions(true,false,true,false)));}
 @Test void actualIndependentAcceptedCounterexampleNowRefusesWithoutChangingDoubleProject()throws Exception{var d=original();var codec=new ProjectCodec();assertEquals(d,codec.decode(codec.encode(d)));var pose=d.evaluateWorld();var error=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(d));assertTrue(error.getMessage().contains("float-precision"),error.getMessage());assertTrue(error.getMessage().contains("tipX")||error.getMessage().contains("originX"),error.getMessage());assertEquals(pose,d.evaluateWorld());}
 @Test void bothBendsOfOriginalRootAreRejectedByActualEndpointError()throws Exception{var d=original();for(boolean bend:new boolean[]{false,true}){var ik=((IkConstraint)d.constraints().get(0)).withOptions(bend,false,true,false);var candidate=d.withConstraints(List.of(ik));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate)).getMessage().contains("float-precision"));}}
 @Test void exactlyRepresentableSaturationAndSafeInteriorRemainAvailable()throws Exception{var d=safe();assertDoesNotThrow(()->RuntimeRange.validate(d));var axis=ModelEdits.editBone(d,id(4),b->b.withLocal(new Transform(460,-20,0,1,1)));assertDoesNotThrow(()->RuntimeRange.validate(axis));}
 @Test void aLongDescendantEndpointCannotHideBehindPassingLinearMatrices()throws Exception{var d=safe();var world=d.evaluateWorld().bones().get(id(3));double length=1e7,desired=Math.acos(-world.origin().x()/length),rotation=Math.toDegrees(desired-Math.atan2(world.matrix().c(),world.matrix().a()));var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(99),"amplified descendant",id(3),new Transform(0,0,rotation,1,1),length));var candidate=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),d.constraints());assertTrue(Math.abs(candidate.evaluateWorld().bones().get(id(99)).tip().x())<1e-6);var e=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(e.getMessage().contains("amplified descendant.tipX"),e.getMessage());assertEquals(candidate,new ProjectCodec().decode(new ProjectCodec().encode(candidate)));}
 @Test void fullTargetHullCrossingSoftSaturationIsRefusedBeforeAnySparseTimeSampling()throws Exception{var d=safe();var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(200.,0.));var candidate=d;var e=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(e.getMessage().contains("float-precision"));assertTrue(e.getMessage().contains("hull")||e.getMessage().contains("budget"),e.getMessage());}
 @Test void boundedInteriorLinearTargetMotionKeepsAWholeRangeProof()throws Exception{var d=safe();var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(5.,-5.));var candidate=d;assertDoesNotThrow(()->RuntimeRange.validate(candidate));}
 @Test void neutralKeysDoNotInventDynamicSoftnessInputs()throws Exception{var d=ModelEdits.editBone(safe(),id(4),b->b.withLocal(new Transform(460,-20,0,1,1)));d=AnimationEdits.put(d,d.animations().get(0).id(),id(4),Channel.TRANSLATE,0,List.of(0.,0.));var candidate=d;assertDoesNotThrow(()->RuntimeRange.validate(candidate));}
 @Test void squareRootErrorEnclosesPositiveDisplacementAtZeroAndAcrossItsFullRange(){var input=new Ik2AcosErrorBounds.E(new Ik2AcosErrorBounds.R(0,10000),.01);var proof=input.sqrt();assertTrue(proof.e()>=.1);for(double value:new double[]{0,1e-12,1e-6,.001,1,100,10000})for(double delta:new double[]{0,.005,.009}){float actual=(float)Math.sqrt((float)(value+delta));assertTrue(Math.abs(actual-Math.sqrt(value))<=proof.e());}}
 @Test void divisionErrorEnclosesActualFloatResultsAndRejectsPossibleZeroDenominator(){var numerator=new Ik2AcosErrorBounds.E(new Ik2AcosErrorBounds.R(-10,20),.001);var denominator=new Ik2AcosErrorBounds.E(new Ik2AcosErrorBounds.R(.1,2),.0001);var proof=numerator.div(denominator);for(double a:new double[]{-10,-1,0,20})for(double b:new double[]{.1,.5,2}){float actual=(float)(a+.0005)/(float)(b-.00005);assertTrue(Math.abs(actual-a/b)<=proof.e());}assertThrows(RuntimeException.class,()->numerator.div(new Ik2AcosErrorBounds.E(new Ik2AcosErrorBounds.R(0,.1),.001)));}
 @Test void animatedParentSignedPiBranchCannotBeHiddenByAnInteriorCosineRange()throws Exception{var d=ModelEdits.editBone(safe(),id(4),b->b.withLocal(new Transform(-130,20,0,1,1)));var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(0.,-80.));var candidate=d;var e=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(e.getMessage().contains("atan2"),e.getMessage());}
 @Test void unrelatedTrackCannotSilentlyChangeTheFloatLoopPeriod()throws Exception{var d=safe();var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(88),"unrelated",id(1),Transform.IDENTITY,0));d=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),d.constraints());var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(5.,-5.));d=AnimationEdits.put(d,clip,id(88),Channel.TRANSLATE,1.1,List.of(1.,0.));var candidate=d;assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate)).getMessage().contains("loop period"));}
 @Test void unprovedBezierTargetIsPreciseAndLossless()throws Exception{var d=safe();var clip=d.animations().get(0).id();d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,0,List.of(0.,0.));d=AnimationEdits.put(d,clip,id(4),Channel.TRANSLATE,1,List.of(10.,0.));d=AnimationEdits.curves(d,clip,Set.of(d.animation(clip).timelines().get(0).keys().get(0).id()),List.of(new Curve(Curve.Kind.BEZIER,.2,40,.8,-40),Curve.LINEAR));var candidate=d;assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate)).getMessage().contains("Bezier target"));}
 @Test void descendantOnlyAnimationMustCertifyItsEndpointAmplification()throws Exception{var d=safe();var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(77),"animated descendant",id(3),Transform.IDENTITY,1));d=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),d.constraints());RuntimeRange.validate(d);d=AnimationEdits.put(d,d.animations().get(0).id(),id(77),Channel.SCALE,1,List.of(1e7,1e7));var candidate=d;var error=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(error.getMessage().contains("float-precision"),error.getMessage());assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));}
 @Test void steppedActivationFromZeroMixSetupCannotBypassTheOriginalCounterexample()throws Exception{var d=original();var ik=(IkConstraint)d.constraints().get(0);var values=ConstraintChannel.IK.values(ik);d=d.withConstraints(List.of(ik.withMix(0)));var old=d.animations().get(0);var key=new Keyframe(id(76),0,values,Collections.nCopies(5,Curve.STEPPED));var clip=new AnimationClip(old.id(),old.name(),old.timelines(),old.deforms(),List.of(new ConstraintTimeline(ik.id(),ConstraintChannel.IK,List.of(key))));d=new DocumentSnapshot(d.bones(),d.slots(),d.attachments(),List.of(clip),d.constraints());var candidate=d;var error=assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(candidate));assertTrue(error.getMessage().contains("float-precision"),error.getMessage());assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));}
}
